import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.CnJ-JtFX.js";const m=JSON.parse('{"title":"术语表","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/glossary.md","filePath":"appendix/glossary.md","lastUpdated":1792683644000}'),o={name:"appendix/glossary.md"};function c(s,t,n,p,l,i){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>本页收录全套教程反复出现的术语。首次阅读遇到不熟悉的词，可以回到这里建立最小定义，再回正文看上下文。</p><table tabindex="0"><thead><tr><th>术语</th><th>一句话定义</th><th>出现章节</th></tr></thead><tbody><tr><td>低代码</td><td>用配置、模型或可视化操作替代重复编码，产出可运行应用的开发方式</td><td>00</td></tr><tr><td>Schema</td><td>用结构化数据描述页面、表单或组件树的配置，通常是 JSON</td><td>00、01、04、16</td></tr><tr><td>渲染器</td><td>读取 Schema 并生成 UI 的运行时；输入是配置，输出是组件树或 DOM</td><td>07、16、17</td></tr><tr><td>设计器</td><td>让用户通过拖拽、属性面板和画布编辑 Schema 的可视化工具</td><td>03、07、10、16、18</td></tr><tr><td>物料</td><td>可被设计器拖入、被渲染器识别的组件资产，含组件实现与元信息</td><td>07、08、17</td></tr><tr><td>物料协议</td><td>描述物料的名称、属性、插槽、默认值与设计态行为的约定</td><td>08</td></tr><tr><td>Setter</td><td>设计器属性面板里编辑某个字段的控件，例如输入框、选择器、颜色选择器</td><td>03、08、18</td></tr><tr><td>资产包</td><td>把一组物料及其元信息打包分发的产物，供设计器与渲染器消费</td><td>08</td></tr><tr><td>插件</td><td>在不改内核的前提下扩展能力的模块，通常通过 <code>setup(api)</code> 注册生命周期</td><td>09、19</td></tr><tr><td>扩展点</td><td>内核暴露给插件的稳定接口，例如注册组件、注册 Setter、监听 Schema 变化</td><td>09、19</td></tr><tr><td>出码</td><td>把 Schema 转换成可读、可运行的源代码，例如 Vue SFC 或 React 组件</td><td>09、20</td></tr><tr><td>运行时</td><td>脱离设计器、只负责解释 Schema 并渲染页面的部分</td><td>07、10、20</td></tr><tr><td>编辑器</td><td>面向搭建者的部分，包含画布、大纲树、属性面板、工具栏</td><td>03、07、10、18</td></tr><tr><td>画布</td><td>设计器中承载页面预览与拖拽交互的区域，可能是 DOM 也可能是 iframe</td><td>07、10、12、18</td></tr><tr><td>大纲树</td><td>以树形结构展示页面节点层级的面板，用于选中、移动、调整嵌套</td><td>07、18</td></tr><tr><td>落点</td><td>拖拽结束时新节点插入的父节点、索引与相对位置</td><td>18</td></tr><tr><td>命令模式</td><td>把每次修改封装成可执行、可撤销的对象，记录 <code>do</code> 与 <code>undo</code></td><td>19</td></tr><tr><td>事务</td><td>把多次修改合并为一次历史记录，避免一次拖拽产生几十条 undo</td><td>19</td></tr><tr><td>撤销 / 重做</td><td>基于历史栈回退或恢复编辑操作，通常由命令模式或快照实现</td><td>13、19</td></tr><tr><td>表达式</td><td>Schema 中用于计算、联动、条件显示的受限脚本片段</td><td>02、05、17</td></tr><tr><td>白名单求值</td><td>只允许预设语法与函数，禁止 <code>eval</code> 与动态代码执行的表达式求值方式</td><td>17</td></tr><tr><td>数据源</td><td>页面从接口、静态数据或上下文获取数据的声明式配置</td><td>02、11</td></tr><tr><td>联动</td><td>一个字段或组件的值变化后，触发其他字段或组件的显示、取值、校验变化</td><td>02、05</td></tr><tr><td>反应式（reactions）</td><td>Formily 中描述字段间依赖关系的声明式机制</td><td>05</td></tr><tr><td>异步校验</td><td>需要调用接口或异步计算才能得出结果的字段校验</td><td>05</td></tr><tr><td>自由画布</td><td>允许像素级拖拽与绝对定位的编辑器形态，典型代表是 GrapesJS</td><td>12</td></tr><tr><td>响应式布局</td><td>页面随视口尺寸变化自动调整布局，不等于响应式数据</td><td>13</td></tr><tr><td>协议版本</td><td>Schema 的版本号，用于校验兼容性与迁移</td><td>16</td></tr><tr><td>错误边界</td><td>渲染子树出错时捕获错误并展示降级 UI，避免整页白屏</td><td>17</td></tr><tr><td>快照</td><td>某一时刻的完整状态副本，常用于简化版撤销重做</td><td>19</td></tr><tr><td>Monorepo</td><td>多个包放在同一仓库并共享依赖管理的工程形态；本教程刻意不使用</td><td>00</td></tr><tr><td>lockfile</td><td>锁定依赖解析结果的清单文件，保证不同机器安装出一致的依赖树</td><td>00</td></tr><tr><td>烟测</td><td>构建或启动后对关键路径做的最小自动化验证</td><td>00、15</td></tr><tr><td>E2E</td><td>端到端测试，从用户操作出发验证完整链路</td><td>15</td></tr></tbody></table><blockquote><p>术语表只给最小定义。需要看具体实现时，按「出现章节」跳转正文；需要看产品差异时，看 <a href="./comparison">产品对照矩阵</a>。</p></blockquote>',4)])])}const _=d(o,[["render",c]]);export{m as __pageData,_ as default};
